function timelinePointer(e) {if(e.button!==0)return;const bar=e.target.closest('.timeline-clip'),lane=e.target.closest('.track-lane,.ruler-lane');if(!lane)return;if(bar){e.preventDefault();stop();switchPreview(false);const type=bar.dataset.type,id=bar.dataset.clip;state.selected={type,id};const c=selectedItem();state.drag={type,id,edge:e.target.dataset.edge||'move',startX:e.clientX,original:clone(c),snapshot:clone(state.project),moved:false};renderInspector();updateTransport();$$('.timeline-clip').forEach(x=>x.classList.toggle('selected',x.dataset.clip===id));}else{const rect=lane.getBoundingClientRect();stop();switchPreview(false);setFrame((e.clientX-rect.left)/state.zoom*state.project.fps);state.drag={scrub:true,lane};}}
function timelineMove(e) {const d=state.drag;if(!d)return;if(d.scrub){const lane=$('.ruler-lane');setFrame((e.clientX-lane.getBoundingClientRect().left)/state.zoom*state.project.fps);return;}if(!d.moved&&Math.abs(e.clientX-d.startX)<3)return;d.moved=true;const c=selectedItem();if(!c)return;const o=d.original,delta=Math.round((e.clientX-d.startX)/state.zoom*state.project.fps),a=c.asset_id?assetById(c.asset_id):null;const max=a&&['video','audio'].includes(a.kind)?Math.floor(a.duration*state.project.fps):Infinity;if(d.edge==='left'){let start=e.altKey?o.start+delta:snapFrame(o.start+delta,c.id);const shift=clamp(start-o.start,Math.max(-o.start,a?.kind==='image'||d.type==='title'?-o.start:-(o.in||0)),o.duration-1);c.start=o.start+shift;if(d.type==='clip')c.in=a?.kind==='image'?0:o.in+shift;c.duration=o.duration-shift;if(o.keyframes?.length)c.keyframes=sliceKeyframes(o,shift,c.duration);}else if(d.edge==='right'){const end=e.altKey?o.start+o.duration+delta:snapFrame(o.start+o.duration+delta,c.id);c.duration=clamp(end-o.start,1,max-(o.in||0));c.keyframes=sliceKeyframes(o,0,c.duration);}else{c.start=e.altKey?Math.max(0,o.start+delta):snapFrame(o.start+delta,c.id);const hover=document.elementFromPoint(e.clientX,e.clientY)?.closest('.track-lane');if(d.type==='clip'&&hover&&hover.dataset.track!=='titles'){const track=Number(hover.dataset.track);if(a?.kind==='audio'?track<0:track>=0)c.track=track;}}if(d.type==='title')c.fade=Math.min(c.fade,Math.floor(c.duration/2));renderTimeline();drawPreview();}
function timelineUp() {const d=state.drag;if(!d)return;state.drag=null;if(d.moved){state.history.push(d.snapshot);if(state.history.length>80)state.history.shift();state.future=[];changed({inspector:true});}}
function fitTimeline() {state.zoom=clamp(($('#timeline-scroll').clientWidth-105)/Math.max(5,durationFrames()/state.project.fps+1),12,160);$('#timeline-zoom').value=state.zoom;renderTimeline();}
async function bootstrap() {try{const b=await api('/api/bootstrap');state.token=b.token;state.projects=b.projects||[];state.capabilities=b.capabilities||{};if(!b.project)throw Error('The server did not provide a project.');adoptProject(b.project);const active=(b.jobs||[]).find(j=>j.project_id===state.project.id&&['queued','running'].includes(j.state));if(active)trackJob(active,active.kind==='render'?'Rendering timeline':active.kind==='blender'?'Rendering Blender scene':'Generating media',active.kind||'render');if(!state.capabilities.ffmpeg)toast('Install FFmpeg and ffprobe to render media, then check engines.',true,8000);}catch(e){toast(`Could not open CINEMATICUM: ${e.message}`,true,30000);$('#preview-note').textContent='Server connection failed';}}

