$('#project-form').addEventListener('submit',async e=>{e.preventDefault();if(state.projectOps){toast('Wait for the current project operation to finish.');return;}const properties={name:$('#new-name').value.trim()||'Untitled film',width:Number($('#new-width').value),height:Number($('#new-height').value),fps:Number($('#new-fps').value)};state.navigating=true;beginProjectOperation();try{if(state.dirty)await saveProject(false);const p=await api('/api/projects',{method:'POST',body:properties});state.projects=await api('/api/projects');if(!Array.isArray(state.projects))state.projects=state.projects.projects||[];adoptProject(p);$('#project-dialog').close();toast('Project created.');}catch(e){toast(e.message,true);}finally{state.navigating=false;endProjectOperation();}});
$('#project-select').addEventListener('change',async e=>{const id=e.target.value;if(state.projectOps){e.target.value=state.project.id;toast('Wait for the current project operation to finish.');return;}state.navigating=true;beginProjectOperation();try{if(state.dirty)await saveProject(false);adoptProject(await api(projectPath(id)));}catch(e){toast(e.message,true);$('#project-select').value=state.project.id;}finally{state.navigating=false;endProjectOperation();}});
$('#rename-project').addEventListener('click',()=>{const name=prompt('Project name',state.project.name);if(name?.trim()){mutate(()=>{state.project.name=name.trim().slice(0,120);});renderProjectList();$('#viewer-project').textContent=state.project.name;}});
window.addEventListener('keydown',e=>{if(!state.project||state.navigating||state.editBusy)return;const editing=e.target.matches('input,textarea,select,[contenteditable]'),dialog=Boolean($('dialog[open]'));if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject().catch(e=>toast(e.message,true));return;}if(editing||dialog)return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);return;}if(e.code==='Space'){e.preventDefault();play().catch(e=>toast(e.message,true));}else if(e.key.toLowerCase()==='s')splitSelected();else if(['Delete','Backspace'].includes(e.key)){e.preventDefault();deleteSelected();}else if(e.key==='ArrowRight'){e.preventDefault();stop();switchPreview(false);setFrame(state.frame+(e.shiftKey?state.project.fps:1));}else if(e.key==='ArrowLeft'){e.preventDefault();stop();switchPreview(false);setFrame(state.frame-(e.shiftKey?state.project.fps:1));}else if(e.key==='Escape'){stop();state.selected=null;renderTimeline();renderInspector();}});
